ee:variables.ee:set-variable:
%dw 2.0
output application/java
var sfValue = ((vars.registry.productLine default vars.req.payload.productLine) default "Neon CRM") as String
var code = upper(trim(sfValue) replace /[^A-Za-z0-9]+/ with "_")
var label = p('provisioning.labelPrefix') ++ "-" ++ (vars.orderId default "") ++ "-" ++ lower(code)
var reporter = trim((p('provisioning.reporterAccountId') default "") as String)
---
{
  salesforceValue:   sfValue,
  code:              code,
  project:           p('jira.project'),
  issueType:         "SYSTEM_SETUP",
  label:             label,
  tags:              [label, p('provisioning.labelPrefix')],
  reporterAccountId: if (isEmpty(reporter)) null else reporter
}

%dw 2.0
import try from dw::Runtime
output application/java
// The registry row is authoritative; the event payload is the fallback (both are written by the Salesforce Flow)
var sfValue = ((vars.registry.productLine default vars.req.payload.productLine) default "") as String
// "Neon CRM" -> NEON_CRM, "Arts People" -> ARTS_PEOPLE: the key used under deactivation.lines in config
var code = upper(trim(sfValue) replace /[^A-Za-z0-9]+/ with "_")
fun cfg(key) = do {
    var r = try(() -> p('deactivation.lines.' ++ code ++ '.' ++ key))
    ---
    if (r.success and !isEmpty(trim((r.result default "") as String))) r.result else null
}
var instanceField  = cfg('instanceField')
var opportunityKey = cfg('opportunityKey')
var instanceId = if (instanceField == null) null else vars.opp.account[instanceField]
var label = p('deactivation.labelPrefix') ++ "-" ++ (vars.opportunityId default "") ++ "-" ++ lower(code)
var deactivationDate = vars.opp.account.deactivationDate
---
{
  salesforceValue: sfValue,
  code:            code,
  project:         cfg('project'),
  issueType:       cfg('issueType'),
  instanceField:   instanceField,
  instanceLabel:   cfg('instanceLabel') default "instance id",
  opportunityKey:  opportunityKey,
  instanceId:      instanceId,
  existingKey:     if (opportunityKey == null) null else vars.opp.deactivation[opportunityKey].jiraKey,
  label:           label,
  tags:            [label, p('deactivation.labelPrefix')],
  // Summary rule (Swati, 1 Oct 2026): "System shutdown for <summaryLabel> /<summarySubject>/" — CRM shows the instance id,
  // Fundraise and Arts People show the Account name
  summaryLabel:    cfg('summaryLabel') default sfValue,
  summarySubject:  if ((cfg('summarySubject') default "instanceId") == "accountName") (vars.opp.account.name default "") else (instanceId default ""),
  // What the ticket says about the date: never a blank after "Deactivation date:" (the receiving team must see a missing date)
  deactivationDateText: if (deactivationDate == null or isEmpty(trim(deactivationDate as String))) p('deactivation.missingDateText')
                        else (deactivationDate as String)
}
